<script setup>
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useWorkspace} from '../stores/workspace.js';import {filterShipments,toCSV} from '../utils/shipments.js';import {statuses,modes} from '../data/seed.js';import Icon from '../components/Icon.vue';import ShipmentTable from '../components/ShipmentTable.vue';import ShipmentForm from '../components/ShipmentForm.vue';import ShipmentDetail from '../components/ShipmentDetail.vue';
const store=useWorkspace(),route=useRoute(),router=useRouter();const search=ref(String(route.query.q||'')),status=ref(statuses.includes(route.query.status)?route.query.status:'All'),mode=ref(modes.includes(route.query.mode)?route.query.mode:'All'),sort=ref('created'),direction=ref('desc'),page=ref(1),pageSize=ref(8),selected=ref(null),form=ref(false),editing=ref(null);
const filtered=computed(()=>filterShipments(store.shipments,{search:search.value,status:status.value,mode:mode.value,sort:sort.value,direction:direction.value}));const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize.value)));const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
watch([search,status,mode,pageSize],()=>{page.value=1;router.replace({query:{...(search.value?{q:search.value}:{}),...(status.value!=='All'?{status:status.value}:{}),...(mode.value!=='All'?{mode:mode.value}:{})}});});watch(()=>route.query.status,v=>{status.value=statuses.includes(v)?v:'All';});watch(pages,v=>{if(page.value>v)page.value=v;});
function changeSort(key){if(sort.value===key)direction.value=direction.value==='asc'?'desc':'asc';else{sort.value=key;direction.value='asc';}page.value=1;}
function edit(s){selected.value=null;editing.value=s;form.value=true;}function reset(){search.value='';status.value='All';mode.value='All';}function exportCSV(){const url=URL.createObjectURL(new Blob([toCSV(filtered.value)],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download='dispatch-shipments.csv';a.click();URL.revokeObjectURL(url);store.notify(`${filtered.value.length} shipments exported.`);}
</script>
<template><div class="page-heading"><div><div class="greeting">EVERY SHIPMENT. ONE CLEAR VIEW.</div><h1>Shipments<span class="heading-count">{{store.shipments.length}}</span></h1><p>From the first booking to the final mile.</p></div><div class="heading-actions"><button class="btn" @click="exportCSV"><Icon name="Download"/>Export CSV</button><button class="btn primary" @click="editing=null;form=true"><Icon name="Plus"/>New shipment</button></div></div><section class="panel shipments-panel"><div class="status-tabs" role="group" aria-label="Filter by status"><button v-for="s in ['All',...statuses]" @click="status=s" :class="{active:status===s}">{{s==='All'?'All shipments':s}}<span>{{s==='All'?store.shipments.length:store.shipments.filter(i=>i.status===s).length}}</span></button></div><div class="table-toolbar"><label class="search-field"><Icon name="Search" :size="17"/><input v-model="search" placeholder="Search ID, customer or route…" aria-label="Search shipments"><button v-if="search" @click="search=''" aria-label="Clear search"><Icon name="X" :size="14"/></button></label><div class="toolbar-right"><label class="select-control"><Icon name="SlidersHorizontal" :size="15"/><select v-model="mode" aria-label="Transport mode"><option value="All">All transport</option><option v-for="m in modes">{{m}}</option></select></label><button v-if="search||status!=='All'||mode!=='All'" class="text-link" @click="reset">Reset filters</button></div></div><ShipmentTable v-if="visible.length" :items="visible" :sort="sort" :direction="direction" :compact="store.settings.compact" @sort="changeSort" @open="selected=$event"/><div v-else class="empty-state"><div class="empty-icon"><Icon name="Search" :size="28"/></div><h2>No shipments found</h2><p>Try another search or clear your filters.</p><button class="btn" @click="reset">Clear filters</button></div><div class="pagination"><span>{{filtered.length?((page-1)*pageSize+1):0}}–{{Math.min(page*pageSize,filtered.length)}} of {{filtered.length}} shipments</span><label>Rows <select v-model.number="pageSize" aria-label="Rows per page"><option :value="8">8</option><option :value="16">16</option><option :value="32">32</option></select></label><div class="page-buttons"><button class="btn" :disabled="page===1" @click="page--" aria-label="Previous page"><Icon name="ChevronLeft" :size="16"/></button><span>{{page}} / {{pages}}</span><button class="btn" :disabled="page>=pages" @click="page++" aria-label="Next page"><Icon name="ChevronRight" :size="16"/></button></div></div></section><p class="page-footnote"><Icon name="Circle" :size="10"/>Local demo data. Click a shipment to see details and update its status.</p><ShipmentForm v-if="form" :shipment="editing" @close="form=false"/><ShipmentDetail v-if="selected" :shipment="selected" @close="selected=null" @edit="edit" @delete="store.remove($event);selected=null"/></template>
